<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Nova compra';$sup=$pdo->query('SELECT id,nome FROM fornecedores WHERE ativo=1 ORDER BY nome')->fetchAll();$products=$pdo->query('SELECT id,nome,custo FROM produtos WHERE ativo=1 ORDER BY nome')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$fid=(int)$_POST['fornecedor_id'];$doc=trim($_POST['numero_documento']??'');$date=$_POST['data_compra']?:today();$discount=number_value($_POST['desconto']??0);$frete=number_value($_POST['frete']??0);$parcelas=(int)($_POST['parcelas']??0);$venc=$_POST['primeiro_vencimento']??today();$interval=max(1,(int)($_POST['intervalo_dias']??30));$obs=trim($_POST['observacoes']??'');$pids=$_POST['produto_id']??[];$qtys=$_POST['quantidade']??[];$costs=$_POST['custo']??[];$items=[];$sub=0;foreach($pids as $k=>$pid){$pid=(int)$pid;$q=number_value($qtys[$k]??0);$c=number_value($costs[$k]??0);if($pid&&$q>0&&$c>=0){$items[]=[(int)$pid,$q,$c,$q*$c];$sub+=$q*$c;}}$total=max(0,$sub-$discount+$frete);if(!$fid||!$items)$error='Fornecedor e pelo menos um item são obrigatórios.';elseif($parcelas<0||$parcelas>60)$error='Quantidade de parcelas inválida.';else{$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO compras(fornecedor_id,numero_documento,data_compra,subtotal,desconto,frete,total,parcelado,observacoes,usuario_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$fid,$doc,$date,$sub,$discount,$frete,$total,$parcelas>0,$obs,current_user()['id']]);$cid=(int)$pdo->lastInsertId();$is=$pdo->prepare('INSERT INTO compra_itens(compra_id,produto_id,quantidade,custo_unitario,subtotal) VALUES(?,?,?,?,?)');foreach($items as $i){$is->execute([$cid,...$i]);$pdo->prepare('UPDATE produtos SET custo=?,atualizado_em=? WHERE id=?')->execute([$i[2],now(),$i[0]]);stock_move($i[0],$i[1],'Compra','compras',$cid,current_user()['id'],'Compra de fornecedor');}if($parcelas>0){$base=round($total/$parcelas,2);$remain=$total;for($i=1;$i<=$parcelas;$i++){$v=$i===$parcelas?round($remain,2):$base;$remain-=$v;$due=date('Y-m-d',strtotime('+'.(($i-1)*$interval).' days',strtotime($venc)));$pdo->prepare('INSERT INTO parcelas(fornecedor_id,compra_id,numero_parcela,quantidade_parcelas,valor,vencimento,status,tipo) VALUES(?,?,?,?,?,?,?,?)')->execute([$fid,$cid,$i,$parcelas,$v,$due,'Pendente','Pagar']);$pdo->prepare("INSERT INTO movimentacoes_financeiras(tipo,categoria,descricao,valor,vencimento,status,usuario_id,origem,referencia_id,criado_em) VALUES('Saída','Compras',?,?,?,?,?,?,?,?)")->execute(['Compra #'.$cid.' parcela '.$i,$v,$due,'Pendente',current_user()['id'],'compra_parcela',(int)$pdo->lastInsertId(),now()]);} }else{$pdo->prepare("INSERT INTO movimentacoes_financeiras(tipo,categoria,descricao,valor,vencimento,data_pagamento,status,usuario_id,origem,referencia_id,criado_em) VALUES('Saída','Compras',?,?,?,?,?,?,?,?,?)")->execute(['Compra #'.$cid,$total,$date,$date,'Pago',current_user()['id'],'compra',$cid,now()]);} $pdo->commit();log_action('compra','compras',$cid);flash('success','Compra registrada e estoque atualizado.');redirect('index.php');}catch(Throwable $e){$pdo->rollBack();$error='Não foi possível finalizar a compra: '.$e->getMessage();}}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Nova compra</h1><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field col-6"><label>Fornecedor</label><select name="fornecedor_id" required><option value="">Selecione</option><?php foreach($sup as $s): ?><option value="<?=$s['id']?>"><?=e($s['nome'])?></option><?php endforeach;?></select></div><div class="field col-3"><label>Número da nota/fatura</label><input name="numero_documento"></div><div class="field col-3"><label>Data</label><input type="date" name="data_compra" value="<?=today()?>"></div><div class="field col-4"><label>Desconto</label><input type="number" step="0.01" min="0" name="desconto" value="0"></div><div class="field col-4"><label>Frete</label><input type="number" step="0.01" min="0" name="frete" value="0"></div><div class="field col-4"><label>Parcelas (0 = à vista)</label><input type="number" min="0" max="60" name="parcelas" value="0"></div><div class="field col-4"><label>1º vencimento</label><input type="date" name="primeiro_vencimento" value="<?=today()?>"></div><div class="field col-4"><label>Intervalo entre parcelas (dias)</label><input type="number" min="1" name="intervalo_dias" value="30"></div><div class="field col-12"><label>Observações</label><textarea name="observacoes"></textarea></div></div><h3 style="margin-top:18px">Itens</h3><div id="compra-items"></div><button type="button" class="btn secondary" onclick="addPurchaseItem()">＋ Adicionar item</button><div class="form-actions"><button class="btn primary">Finalizar compra</button></div></form></div><script>const PURCHASE_PRODUCTS=<?=json_encode($products,JSON_UNESCAPED_UNICODE)?>;function addPurchaseItem(){const c=document.getElementById('compra-items');const r=document.createElement('div');r.className='form-grid card';r.style.marginBottom='10px';r.innerHTML='<div class="field col-6"><label>Produto</label><select name="produto_id[]">'+PURCHASE_PRODUCTS.map(p=>`<option value="${p.id}" data-cost="${p.custo}">${p.nome.replaceAll("'","\\'")}</option>`).join('')+'</select></div><div class="field col-2"><label>Quantidade</label><input type="number" min="0.01" step="0.01" name="quantidade[]" value="1"></div><div class="field col-3"><label>Custo unitário</label><input type="number" min="0" step="0.01" name="custo[]" value="0"></div><div class="col-1" style="align-self:end"><button type="button" class="btn danger" onclick="this.closest('.card').remove()">×</button></div>';c.appendChild(r)}addPurchaseItem();</script><?php include __DIR__.'/../../includes/footer.php'; ?>
